#!/usr/bin/env python3
from __future__ import annotations

import base64
import json
import sys
from collections import Counter
from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parents[3]
SYSTEM = ROOT / "content" / "pattern-system"
COL = SYSTEM / "collections" / "baby-nursery"
SRC_IMG = COL / "source-designs" / "I0001-teddy-bear.png"
PATTERNS = SYSTEM / "patterns"

sys.path.insert(0, str((SYSTEM / "multitech").resolve()))
import bulk_generate as bg  # noqa: E402

FULL_FEET_PNG_B64 = """"""

SYMBOLS = list("ABCDEFGHJKLMNPQRSTUVWXYZ23456789")
GRID = {"CS": (100,120), "C2C": (60,72), "TC": (80,96), "LH": (60,72)}

def read_json(p: Path):
    return json.loads(p.read_text(encoding="utf-8"))

def write_json(p: Path, d):
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(d, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

def rgb(hexv: str):
    h=hexv.lstrip("#")
    return tuple(int(h[i:i+2],16) for i in (0,2,4))

def main():
    SRC_IMG.parent.mkdir(parents=True, exist_ok=True)
    SRC_IMG.write_bytes(base64.b64decode(FULL_FEET_PNG_B64))
    im = Image.open(SRC_IMG).convert("RGBA")
    if im.size != (800,960):
        raise RuntimeError(f"Unexpected source size {im.size}")
    bbox = im.getchannel("A").getbbox()
    if bbox != (16,96,784,864):
        raise RuntimeError(f"Unexpected full-feet alpha bbox {bbox}")

    collection = read_json(COL / "collection.json")
    palette = collection["palette"]
    exact = {rgb(p["hex"]): i for i,p in enumerate(palette)}

    matrix=[]
    counts=Counter()
    px=im.load()
    for gy in range(120):
        row=[]
        for gx in range(100):
            r,g,b,a = px[gx*8+4, gy*8+4]
            if a == 0:
                row.append(None)
                continue
            idx = exact.get((r,g,b))
            if idx is None:
                idx = min(range(len(palette)), key=lambda i: sum((rgb(palette[i]["hex"])[k]-(r,g,b)[k])**2 for k in range(3)))
            sym = SYMBOLS[idx]
            row.append(sym)
            counts[sym] += 1
        matrix.append(row)

    threads=[]
    for i,p in enumerate(palette):
        sym=SYMBOLS[i]
        if counts[sym]:
            threads.append({
                "symbol":sym,
                "dmc":str(p["dmc"]),
                "color":str(p["hex"]).upper(),
                "name":p.get("name", f"DMC {p['dmc']}"),
                "stitches":counts[sym],
            })

    cs_path=PATTERNS/"I0001-CS"/"pattern.json"
    cs=read_json(cs_path)
    cs.update({
        "matrix":matrix,
        "threads":threads,
        "total_stitches":sum(counts.values()),
        "stitch_width":100,
        "stitch_height":120,
        "source_asset":"collections/baby-nursery/source-designs/I0001-teddy-bear.png",
        "status":"ready",
    })
    write_json(cs_path,cs)

    for suffix in ("C2C","TC","LH"):
        w,h=GRID[suffix]
        m,t=bg.downsample(matrix,threads,w,h)
        total=sum(1 for row in m for v in row if v)
        pth=PATTERNS/f"I0001-{suffix}"/"pattern.json"
        p=read_json(pth)
        p.update({
            "matrix":m,
            "threads":t,
            "total_stitches":total,
            "stitch_width":w,
            "stitch_height":h,
            "source_asset":"collections/baby-nursery/source-designs/I0001-teddy-bear.png",
            "status":"ready",
        })
        write_json(pth,p)

    # Keep the corrected crochet cover mapping explicit in product JSONs.
    expected = {
        "CS":"collections/baby-nursery/assets/cover-cross-stitch.jpg",
        "C2C":"collections/baby-nursery/assets/cover-crochet.jpg",
        "TC":"collections/baby-nursery/assets/cover-c2c-crochet.jpg",
        "LH":"collections/baby-nursery/assets/cover-rug.jpg",
    }
    for suffix,path in expected.items():
        prod=SYSTEM/"products"/f"I0001-{suffix}"/"product.json"
        d=read_json(prod)
        d["source_artwork"]="collections/baby-nursery/source-designs/I0001-teddy-bear.png"
        d["page_1_asset"]=path
        d["render_ready"]=True
        write_json(prod,d)

    print("I0001_FULL_FEET_RELEASE_APPLIED")
    print("SOURCE_BBOX", bbox)
    print("CS_STITCHES", sum(counts.values()))
    print("CS_COLORS", len(threads))

if __name__ == "__main__":
    main()
